if(TEXT.FORMULA&&TEXT.FORMULA.TITLE){var accordion=getAccordionByTitle(TEXT.FORMULA.TITLE);var video=null;if(accordion){accordion.dataset.element="formula-and-care-benefits";if(accordion.querySelector("video")){video=accordion.querySelector("video").closest(".block").outerHTML;video=video.replace("data-src=","src=");video=video.replace('preload="none"','preload="metadata"');}}
if(TEXT.FORMULA.EDITORIAL){var accordionBody=formulaAndCare();utag.helpers.common.addDrawerAccordion("formula-and-care-benefits",TEXT.FORMULA.TITLE,accordionBody,productDetails);}}
